  php.writeFile(
    '/arena/vendor/symfony/var-dumper/Command/Descriptor/HtmlDescriptor.php',
    "<?php\n\n/*\n * This file is part of the Symfony package.\n *\n * (c) Fabien Potencier <fabien@symfony.com>\n *\n * For the full copyright and license information, please view the LICENSE\n * file that was distributed with this source code.\n */\n\nnamespace Symfony\\Component\\VarDumper\\Command\\Descriptor;\n\nuse Symfony\\Component\\Console\\Output\\OutputInterface;\nuse Symfony\\Component\\VarDumper\\Cloner\\Data;\nuse Symfony\\Component\\VarDumper\\Dumper\\HtmlDumper;\n\n/**\n * Describe collected data clones for html output.\n *\n * @author Maxime Steinhausser <maxime.steinhausser@gmail.com>\n *\n * @final\n */\nclass HtmlDescriptor implements DumpDescriptorInterface\n{\n    private bool $initialized = false;\n\n    public function __construct(\n        private HtmlDumper $dumper,\n    ) {\n    }\n\n    public function describe(OutputInterface $output, Data $data, array $context, int $clientId): void\n    {\n        if (!$this->initialized) {\n            $styles = file_get_contents(__DIR__.'/../../Resources/css/htmlDescriptor.css');\n            $scripts = file_get_contents(__DIR__.'/../../Resources/js/htmlDescriptor.js');\n            $output->writeln(\"<style>$styles</style><script>$scripts</script>\");\n            $this->initialized = true;\n        }\n\n        $title = '-';\n        if (isset($context['request'])) {\n            $request = $context['request'];\n            $controller = \"<span class='dumped-tag'>{$this->dumper->dump($request['controller'], true, ['maxDepth' => 0])}</span>\";\n            $title = \\sprintf('<code>%s</code> <a href=\"%s\">%s</a>', self::escape($request['method']), $uri = self::escape($request['uri']), $uri);\n            $dedupIdentifier = self::escape($request['identifier']);\n        } elseif (isset($context['cli'])) {\n            $title = '<code>$ </code>'.self::escape($context['cli']['command_line']);\n            $dedupIdentifier = self::escape($context['cli']['identifier']);\n        } else {\n            $dedupIdentifier = bin2hex(random_bytes(4));\n        }\n\n        $sourceDescription = '';\n        if (isset($context['source'])) {\n            $source = $context['source'];\n            $projectDir = isset($source['project_dir']) ? self::escape($source['project_dir']) : null;\n            $sourceDescription = \\sprintf('%s on line %d', self::escape($source['name']), $source['line']);\n            if (isset($source['file_link'])) {\n                $sourceDescription = \\sprintf('<a href=\"%s\">%s</a>', self::escape($source['file_link']), $sourceDescription);\n            }\n        }\n\n        $isoDate = $this->extractDate($context, 'c');\n        $tags = array_filter([\n            'controller' => $controller ?? null,\n            'project dir' => $projectDir ?? null,\n        ]);\n\n        $output->writeln(<<<HTML\n            <article data-dedup-id=\"$dedupIdentifier\">\n                <header>\n                    <div class=\"row\">\n                        <h2 class=\"col\">$title</h2>\n                        <time class=\"col text-small\" title=\"$isoDate\" datetime=\"$isoDate\">\n                            {$this->extractDate($context)}\n                        </time>\n                    </div>\n                    {$this->renderTags($tags)}\n                </header>\n                <section class=\"body\">\n                    <p class=\"text-small\">\n                        $sourceDescription\n                    </p>\n                    {$this->dumper->dump($data, true)}\n                </section>\n            </article>\n            HTML\n        );\n    }\n\n    private function extractDate(array $context, string $format = 'r'): string\n    {\n        return date($format, (int) $context['timestamp']);\n    }\n\n    private function renderTags(array $tags): string\n    {\n        if (!$tags) {\n            return '';\n        }\n\n        $renderedTags = '';\n        foreach ($tags as $key => $value) {\n            $renderedTags .= \\sprintf('<li><span class=\"badge\">%s</span>%s</li>', $key, $value);\n        }\n\n        return <<<HTML\n            <div class=\"row\">\n                <ul class=\"tags\">\n                    $renderedTags\n                </ul>\n            </div>\n            HTML;\n    }\n\n    private static function escape(string $value): string\n    {\n        return htmlspecialchars($value, \\ENT_QUOTES | \\ENT_SUBSTITUTE, 'UTF-8');\n    }\n}\n",
  )

  php.writeFile(
    '/arena/vendor/symfony/var-dumper/Command/ServerDumpCommand.php',
    "<?php\n\n/*\n * This file is part of the Symfony package.\n *\n * (c) Fabien Potencier <fabien@symfony.com>\n *\n * For the full copyright and license information, please view the LICENSE\n * file that was distributed with this source code.\n */\n\nnamespace Symfony\\Component\\VarDumper\\Command;\n\nuse Symfony\\Component\\Console\\Attribute\\AsCommand;\nuse Symfony\\Component\\Console\\Command\\Command;\nuse Symfony\\Component\\Console\\Completion\\CompletionInput;\nuse Symfony\\Component\\Console\\Completion\\CompletionSuggestions;\nuse Symfony\\Component\\Console\\Exception\\InvalidArgumentException;\nuse Symfony\\Component\\Console\\Input\\InputInterface;\nuse Symfony\\Component\\Console\\Input\\InputOption;\nuse Symfony\\Component\\Console\\Output\\OutputInterface;\nuse Symfony\\Component\\Console\\Style\\SymfonyStyle;\nuse Symfony\\Component\\VarDumper\\Cloner\\Data;\nuse Symfony\\Component\\VarDumper\\Command\\Descriptor\\CliDescriptor;\nuse Symfony\\Component\\VarDumper\\Command\\Descriptor\\DumpDescriptorInterface;\nuse Symfony\\Component\\VarDumper\\Command\\Descriptor\\HtmlDescriptor;\nuse Symfony\\Component\\VarDumper\\Dumper\\CliDumper;\nuse Symfony\\Component\\VarDumper\\Dumper\\HtmlDumper;\nuse Symfony\\Component\\VarDumper\\Server\\DumpServer;\n\n/**\n * Starts a dump server to collect and output dumps on a single place with multiple formats support.\n *\n * @author Maxime Steinhausser <maxime.steinhausser@gmail.com>\n *\n * @final\n */\n#[AsCommand(name: 'server:dump', description: 'Start a dump server that collects and displays dumps in a single place')]\nclass ServerDumpCommand extends Command\n{\n    /** @var DumpDescriptorInterface[] */\n    private array $descriptors;\n\n    public function __construct(\n        private DumpServer $server,\n        array $descriptors = [],\n    ) {\n        $this->descriptors = $descriptors + [\n            'cli' => new CliDescriptor(new CliDumper()),\n            'html' => new HtmlDescriptor(new HtmlDumper()),\n        ];\n\n        parent::__construct();\n    }\n\n    protected function configure(): void\n    {\n        $this\n            ->addOption('format', null, InputOption::VALUE_REQUIRED, \\sprintf('The output format (%s)', implode(', ', $this->getAvailableFormats())), 'cli')\n            ->setHelp(<<<'EOF'\n                <info>%command.name%</info> starts a dump server that collects and displays\n                dumps in a single place for debugging you application:\n\n                  <info>php %command.full_name%</info>\n\n                You can consult dumped data in HTML format in your browser by providing the <info>--format=html</info> option\n                and redirecting the output to a file:\n\n                  <info>php %command.full_name% --format=\"html\" > dump.html</info>\n\n                EOF\n            )\n        ;\n    }\n\n    protected function execute(InputInterface $input, OutputInterface $output): int\n    {\n        $io = new SymfonyStyle($input, $output);\n        $format = $input->getOption('format');\n\n        if (!$descriptor = $this->descriptors[$format] ?? null) {\n            throw new InvalidArgumentException(\\sprintf('Unsupported format \"%s\".', $format));\n        }\n\n        $errorIo = $io->getErrorStyle();\n        $errorIo->title('Symfony Var Dumper Server');\n\n        $this->server->start();\n\n        $errorIo->success(\\sprintf('Server listening on %s', $this->server->getHost()));\n        $errorIo->comment('Quit the server with CONTROL-C.');\n\n        $this->server->listen(static function (Data $data, array $context, int $clientId) use ($descriptor, $io) {\n            $descriptor->describe($io, $data, $context, $clientId);\n        });\n\n        return 0;\n    }\n\n    public function complete(CompletionInput $input, CompletionSuggestions $suggestions): void\n    {\n        if ($input->mustSuggestOptionValuesFor('format')) {\n            $suggestions->suggestValues($this->getAvailableFormats());\n        }\n    }\n\n    private function getAvailableFormats(): array\n    {\n        return array_keys($this->descriptors);\n    }\n}\n",
  )

